	"deleted_at" timestamp with time zone,
	"assigned_to" uuid NOT NULL,
	"assigned_by" uuid NOT NULL,
	"task" text NOT NULL,
	"level" "delegation_level" DEFAULT 'L2' NOT NULL,
	"date_given" date DEFAULT today_ist() NOT NULL,
	"expected_date" date NOT NULL,
	"status" "delegation_status" DEFAULT 'Not Started' NOT NULL,
	"completed_at" date,
	"blocker_note" text,
	CONSTRAINT "delegation_done_needs_completed_at" CHECK ("delegation_task"."status" <> 'Done' OR "delegation_task"."completed_at" IS NOT NULL),
	CONSTRAINT "delegation_blocked_needs_note" CHECK ("delegation_task"."status" <> 'Blocked' OR ("delegation_task"."blocker_note" IS NOT NULL AND length(trim("delegation_task"."blocker_note")) > 0)),
	CONSTRAINT "delegation_completed_at_only_when_done" CHECK ("delegation_task"."completed_at" IS NULL OR "delegation_task"."status" = 'Done'),
	CONSTRAINT "delegation_expected_after_given" CHECK ("delegation_task"."expected_date" >= "delegation_task"."date_given")
);
